-- ── story 6-1b: owner two-factor sign-in ─────────────────────────────────
-- Generated by drizzle-kit (the two tables, the eleven `users` columns, the
-- indexes) and hand-amended below the marker: the CHECKs, RLS on both new
-- tables, the session revoke-reason CHECK re-added with the two new reasons,
-- and the post-migration probe (drizzle-kit is blind to all of them;
-- `bun run db:generate` afterwards reports "No schema changes").
--
-- Additive: `sign_in_challenges` and `user_backup_codes` (tenant-scoped,
-- RLS) and nullable / zero-defaulted `users.mfa_*` columns. No data is
-- rewritten. No foreign keys (IMPLEMENTATION-GUIDE §3).
--
-- Lock cost: re-adding `sessions_revoked_reason_check` takes an ACCESS
-- EXCLUSIVE lock on `sessions` and scans it. The table holds only live
-- sessions and those ended within 30 days (the purge), which is acceptable
-- at deploy.
CREATE TABLE "sign_in_challenges" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"user_id" uuid NOT NULL,
	"purpose" text NOT NULL,
	"secret_hash" text NOT NULL,
	"enabled_at_seen" timestamp with time zone,
	"failures" integer DEFAULT 0 NOT NULL,
	"ip" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"consumed_at" timestamp with time zone
);
--> statement-breakpoint
CREATE TABLE "user_backup_codes" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"user_id" uuid NOT NULL,
	"code_hash" text NOT NULL,
	"used_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
ALTER TABLE "users" ADD COLUMN "mfa_secret_sealed" text;--> statement-breakpoint
ALTER TABLE "users" ADD COLUMN "mfa_enabled_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "users" ADD COLUMN "mfa_last_step" bigint;--> statement-breakpoint
ALTER TABLE "users" ADD COLUMN "mfa_failures" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "users" ADD COLUMN "mfa_lock_cycles" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "users" ADD COLUMN "mfa_failed_since_success" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "users" ADD COLUMN "mfa_locked_until" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "users" ADD COLUMN "mfa_pending_secret_sealed" text;--> statement-breakpoint
ALTER TABLE "users" ADD COLUMN "mfa_pending_created_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "users" ADD COLUMN "mfa_enrol_code_hash" text;--> statement-breakpoint
ALTER TABLE "users" ADD COLUMN "mfa_enrol_code_expires_at" timestamp with time zone;--> statement-breakpoint
CREATE INDEX "sign_in_challenges_expires_at_idx" ON "sign_in_challenges" USING btree ("expires_at");--> statement-breakpoint
CREATE INDEX "sign_in_challenges_open_idx" ON "sign_in_challenges" USING btree ("tenant_id","user_id") WHERE consumed_at is null;--> statement-breakpoint
CREATE UNIQUE INDEX "user_backup_codes_user_code_unique" ON "user_backup_codes" USING btree ("user_id","code_hash");--> statement-breakpoint
CREATE INDEX "user_backup_codes_unused_idx" ON "user_backup_codes" USING btree ("user_id") WHERE used_at is null;
--> statement-breakpoint
-- ── hand-amended: the CHECKs (IMPLEMENTATION-GUIDE §3, §4) ─────────────────
-- Each secret is paired with its date, the enrolment code hash with its
-- expiry; every counter is non-negative. Nullable columns say IS NULL first.
ALTER TABLE "users" ADD CONSTRAINT "users_mfa_secret_pairing" CHECK (("mfa_secret_sealed" IS NULL) = ("mfa_enabled_at" IS NULL));--> statement-breakpoint
ALTER TABLE "users" ADD CONSTRAINT "users_mfa_pending_pairing" CHECK (("mfa_pending_secret_sealed" IS NULL) = ("mfa_pending_created_at" IS NULL));--> statement-breakpoint
ALTER TABLE "users" ADD CONSTRAINT "users_mfa_enrol_code_pairing" CHECK (("mfa_enrol_code_hash" IS NULL) = ("mfa_enrol_code_expires_at" IS NULL));--> statement-breakpoint
ALTER TABLE "users" ADD CONSTRAINT "users_mfa_counters_check" CHECK (
	("mfa_last_step" IS NULL OR "mfa_last_step" >= 0)
	AND "mfa_failures" >= 0 AND "mfa_lock_cycles" >= 0 AND "mfa_failed_since_success" >= 0
);--> statement-breakpoint
-- Pinned against `SIGN_IN_CHALLENGE_PURPOSES` (modules/tenancy/second-factor.ts) by test/second-factor.spec.ts.
ALTER TABLE "sign_in_challenges" ADD CONSTRAINT "sign_in_challenges_purpose_check" CHECK ("purpose" IN ('totp', 'enroll'));--> statement-breakpoint
ALTER TABLE "sign_in_challenges" ADD CONSTRAINT "sign_in_challenges_failures_check" CHECK ("failures" BETWEEN 0 AND 5);--> statement-breakpoint
ALTER TABLE "sign_in_challenges" ADD CONSTRAINT "sign_in_challenges_window_check" CHECK ("expires_at" > "created_at");--> statement-breakpoint
-- A `totp` challenge records the factor it was issued against; an `enroll` one has none.
ALTER TABLE "sign_in_challenges" ADD CONSTRAINT "sign_in_challenges_purpose_shape_check" CHECK (("purpose" = 'totp') = ("enabled_at_seen" IS NOT NULL));--> statement-breakpoint
-- ── hand-amended: the session revoke reasons gain the two 6-1b reasons ─────
-- Pinned against `SESSION_REVOKE_REASONS` (modules/tenancy/sessions.ts) by test/sessions.spec.ts.
ALTER TABLE "sessions" DROP CONSTRAINT "sessions_revoked_reason_check";--> statement-breakpoint
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_revoked_reason_check" CHECK (
	("revoked_at" IS NULL) = ("revoked_reason" IS NULL)
	AND ("revoked_reason" IS NULL OR "revoked_reason" IN (
		'signed-out', 'deactivated', 'role-changed', 'client-suspended', 'refresh-reuse', 'released', 'device-revoked',
		'second-factor-reset', 'second-factor-changed'
	))
);--> statement-breakpoint
-- ── hand-amended: RLS — the uniform tenant policy ─────────────────────────
ALTER TABLE "sign_in_challenges" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "sign_in_challenges_tenant_isolation" ON "sign_in_challenges"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
ALTER TABLE "user_backup_codes" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "user_backup_codes_tenant_isolation" ON "user_backup_codes"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
-- ── the post-migration assertion (the 0064/0074 model) ────────────────────
DO $$
DECLARE
	t uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (1) accepted shapes, rolled back by a sentinel: the two new revoke
	-- reasons, an enrolled user with every mfa column set, both challenge
	-- purposes at the failure bounds, a backup code.
	BEGIN
		INSERT INTO "sessions" ("id","tenant_id","user_id","kind","refresh_hash","idle_expires_at","absolute_expires_at","revoked_at","revoked_reason")
		VALUES (gen_random_uuid(), t, u, 'web', 'h1-0075', now(), now(), now(), 'second-factor-reset'),
		       (gen_random_uuid(), t, u, 'web', 'h2-0075', now(), now(), now(), 'second-factor-changed');
		INSERT INTO "users" ("id","tenant_id","email","password_hash","role","status",
		                     "mfa_secret_sealed","mfa_enabled_at","mfa_last_step","mfa_failures","mfa_lock_cycles","mfa_failed_since_success","mfa_locked_until",
		                     "mfa_pending_secret_sealed","mfa_pending_created_at","mfa_enrol_code_hash","mfa_enrol_code_expires_at")
		VALUES (gen_random_uuid(), t, 'probe-0075-a@example.invalid', 'x', 'owner', 'active',
		        's', now(), 0, 5, 3, 7, 'infinity', 'p', now(), 'h', now() + interval '72 hours');
		INSERT INTO "sign_in_challenges" ("id","tenant_id","user_id","purpose","secret_hash","enabled_at_seen","failures","ip","expires_at")
		VALUES (gen_random_uuid(), t, u, 'totp', 'h', now(), 0, '127.0.0.1', now() + interval '5 minutes'),
		       (gen_random_uuid(), t, u, 'enroll', 'h', NULL, 5, '127.0.0.1', now() + interval '10 minutes');
		INSERT INTO "user_backup_codes" ("id","tenant_id","user_id","code_hash") VALUES (gen_random_uuid(), t, u, 'h');
		RAISE EXCEPTION USING ERRCODE = 'P0075', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation THEN
			RAISE EXCEPTION 'migration 0075: an accepted shape was refused.';
		WHEN SQLSTATE 'P0075' THEN
			NULL;
	END;
	-- (2) refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY[
		'unknown revoke reason', 'secret without a date', 'date without a secret', 'pending without a date',
		'enrol code without an expiry', 'negative failures', 'negative last step',
		'unknown purpose', 'challenge failures over 5', 'negative challenge failures', 'challenge expiring at creation',
		'totp without the factor seen', 'enroll with a factor seen'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'unknown revoke reason' THEN 'sessions_revoked_reason_check'
			WHEN 'secret without a date' THEN 'users_mfa_secret_pairing'
			WHEN 'date without a secret' THEN 'users_mfa_secret_pairing'
			WHEN 'pending without a date' THEN 'users_mfa_pending_pairing'
			WHEN 'enrol code without an expiry' THEN 'users_mfa_enrol_code_pairing'
			WHEN 'negative failures' THEN 'users_mfa_counters_check'
			WHEN 'negative last step' THEN 'users_mfa_counters_check'
			WHEN 'unknown purpose' THEN 'sign_in_challenges_purpose_check'
			WHEN 'challenge failures over 5' THEN 'sign_in_challenges_failures_check'
			WHEN 'negative challenge failures' THEN 'sign_in_challenges_failures_check'
			WHEN 'challenge expiring at creation' THEN 'sign_in_challenges_window_check'
			ELSE 'sign_in_challenges_purpose_shape_check'
		END;
		BEGIN
			CASE probe
				WHEN 'unknown revoke reason' THEN
					INSERT INTO "sessions" ("id","tenant_id","user_id","kind","idle_expires_at","absolute_expires_at","revoked_at","revoked_reason") VALUES (gen_random_uuid(), t, u, 'web', now(), now(), now(), 'second-factor');
				WHEN 'secret without a date' THEN
					INSERT INTO "users" ("id","tenant_id","email","password_hash","mfa_secret_sealed") VALUES (gen_random_uuid(), t, 'p1-0075@example.invalid', 'x', 's');
				WHEN 'date without a secret' THEN
					INSERT INTO "users" ("id","tenant_id","email","password_hash","mfa_enabled_at") VALUES (gen_random_uuid(), t, 'p2-0075@example.invalid', 'x', now());
				WHEN 'pending without a date' THEN
					INSERT INTO "users" ("id","tenant_id","email","password_hash","mfa_pending_secret_sealed") VALUES (gen_random_uuid(), t, 'p3-0075@example.invalid', 'x', 'p');
				WHEN 'enrol code without an expiry' THEN
					INSERT INTO "users" ("id","tenant_id","email","password_hash","mfa_enrol_code_hash") VALUES (gen_random_uuid(), t, 'p4-0075@example.invalid', 'x', 'h');
				WHEN 'negative failures' THEN
					INSERT INTO "users" ("id","tenant_id","email","password_hash","mfa_failures") VALUES (gen_random_uuid(), t, 'p5-0075@example.invalid', 'x', -1);
				WHEN 'negative last step' THEN
					INSERT INTO "users" ("id","tenant_id","email","password_hash","mfa_last_step") VALUES (gen_random_uuid(), t, 'p6-0075@example.invalid', 'x', -1);
				WHEN 'unknown purpose' THEN
					INSERT INTO "sign_in_challenges" ("id","tenant_id","user_id","purpose","secret_hash","ip","expires_at") VALUES (gen_random_uuid(), t, u, 'sms', 'h', 'ip', now() + interval '1 minute');
				WHEN 'challenge failures over 5' THEN
					INSERT INTO "sign_in_challenges" ("id","tenant_id","user_id","purpose","secret_hash","failures","ip","expires_at") VALUES (gen_random_uuid(), t, u, 'enroll', 'h', 6, 'ip', now() + interval '1 minute');
				WHEN 'negative challenge failures' THEN
					INSERT INTO "sign_in_challenges" ("id","tenant_id","user_id","purpose","secret_hash","failures","ip","expires_at") VALUES (gen_random_uuid(), t, u, 'enroll', 'h', -1, 'ip', now() + interval '1 minute');
				WHEN 'challenge expiring at creation' THEN
					INSERT INTO "sign_in_challenges" ("id","tenant_id","user_id","purpose","secret_hash","ip","expires_at") VALUES (gen_random_uuid(), t, u, 'enroll', 'h', 'ip', now());
				WHEN 'totp without the factor seen' THEN
					INSERT INTO "sign_in_challenges" ("id","tenant_id","user_id","purpose","secret_hash","ip","expires_at") VALUES (gen_random_uuid(), t, u, 'totp', 'h', 'ip', now() + interval '1 minute');
				WHEN 'enroll with a factor seen' THEN
					INSERT INTO "sign_in_challenges" ("id","tenant_id","user_id","purpose","secret_hash","enabled_at_seen","ip","expires_at") VALUES (gen_random_uuid(), t, u, 'enroll', 'h', now(), 'ip', now() + interval '1 minute');
			END CASE;
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0075: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
END $$;
